public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (start == null || end == null || start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Start and end coordinates must be length 2 arrays.");
    }
    // Helper to convert coordinates to key
    java.util.function.Function<int[], String> coordKey = p -> p[0] + "," + p[1];

    // Build adjacency map
    java.util.Map<String, java.util.Set<String>> graph = new java.util.HashMap<>();

    for (int[] edge : paths) {
        if (edge.length != 4) {
            continue; // ignore invalid edges
        }
        int x1 = edge[0];
        int y1 = edge[1];
        int x2 = edge[2];
        int y2 = edge[3];

        // Optionally validate bounds
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n ||
            x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            continue;
        }

        String key1 = x1 + "," + y1;
        String key2 = x2 + "," + y2;
        graph.computeIfAbsent(key1, k -> new java.util.HashSet<>()).add(key2);
        graph.computeIfAbsent(key2, k -> new java.util.HashSet<>()).add(key1);
    }

    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];

    // If start or end not in graph, still allowed if they equal
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String curr = queue.poll();
        java.util.Set<String> neighbors = graph.getOrDefault(curr, java.util.Collections.emptySet());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(nb);
                queue.offer(nb);
            }
        }
    }

    return "cannot be travelled";
}

