public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date string cannot be null");
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Date must be in the format \"MM dd yyyy\"");
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day   = Integer.parseInt(parts[1]);
        int year  = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.format.TextStyle textStyle = java.time.format.TextStyle.FULL;
        java.util.Locale locale = java.util.Locale.ENGLISH;

        String monthName = localDate.getMonth().getDisplayName(textStyle, locale);
        String weekday   = localDate.getDayOfWeek().getDisplayName(textStyle, locale);

        return java.lang.String.format("%s %d, %d is a %s", monthName, localDate.getDayOfMonth(), year, weekday);
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid date: " + date, e);
    }
}

