public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;

    boolean[][] adj = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                adj[i][j] = true;
            }
        }
    }

    int maxMask = 1 << n;
    int[][] dp = new int[maxMask][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }

    for (int mask = 1; mask < maxMask; mask++) {
        for (int last = 0; last < n; last++) {
            int cur = dp[mask][last];
            if (cur == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) == 0 && adj[last][next]) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }

    int fullMask = maxMask - 1;
    long total = 0;
    for (int last = 0; last < n; last++) {
        total += dp[fullMask][last];
    }
    return (int) total;
}

