public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int sqrt = (int) Math.sqrt(n);
    if (sqrt * sqrt == n) return 1;
    for (int i = 1; i <= sqrt; i++) {
        int remainder = n - i * i;
        int rSqrt = (int) Math.sqrt(remainder);
        if (rSqrt * rSqrt == remainder) return 2;
    }
    int temp = n;
    while (temp % 4 == 0) temp /= 4;
    if (temp % 8 == 7) return 4;
    return 3;
}

